--叠加速度
function AddV1(o, v, a)
	o.vx = o.vx + v * cos(a)
	o.vy = o.vy + v * sin(a)
end
egg.AddV1 = AddV1

function AddV2(o, vx, vy)
	o.vx = o.vx + vx
	o.vy = o.vy + vy
end
egg.AddV2 = AddV2

--叠加加速度
function AddA1(o, acc, a)
	o.ax = o.ax + acc * cos(a)
	o.ay = o.ay + acc * sin(a)
end
egg.AddA1 = AddA1

function AddA2(o, ax, ay)
	o.ax = o.ax + ax
	o.ay = o.ay + ay
end
egg.AddA2 = AddA2
