--一个可以同时均匀改变速度大小和方向的事件
---@param o  @目标对象
---{[1] = v0, --初速度，为nil则获取目标当前速度
---[2] = v1, --末速度，为nil则获取目标当前速度
---[3] = a0, --初始方向，为nil则获取目标当前方向
---[4] = da, --方向变化总量
---[5] = tv, --速度大小变化时间
---[6] = ta, --速度方向变化时间
---}
function ChV(o, v0, v1, a0, da, tv, ta)
	--change v 同时改变速度大小和方向事件
	local dv
	task.New(o, function()
		dv, da = (v1 - v0) / tv, da / ta
		if tv > ta then
			for _ = 1, ta do
				v0 = v0 + dv
				a0 = a0 + da
				SetV(o, v0, a0)
				task.Wait(1)
			end
			for _ = ta, tv do
				v0 = v0 + dv
				SetV(o, v0, a0)
				task.Wait(1)
			end
		else
			for _ = 1, tv do
				v0 = v0 + dv
				a0 = a0 + da
				SetV(o, v0, a0)
				task.Wait(1)
			end
			for _ = tv, ta do
				a0 = a0 + da
				SetV(o, v0, a0)
				task.Wait(1)
			end
		end
	end)
end
egg.ChV = ChV

--简易的均匀改变速度大小的事件
---@param o   @目标对象
---@param v0 number @设置初速度
---@param v1 number @设置末速度
---@param a0 number @设置方向
---@param t0 number @设置变化时间
function SimStrChV(o, v0, v1, a0, t0, nowait)
	if nowait == true then
		local road = {}
		local v, a = 0, 0
		local _v0, _v1, _a0, _t0 = v0 or v, v1 or v, a0 or a, t0 or 1
		local _x, _y = 0, 0
		local vx, vy = _v0 * cos(_a0), _v0 * sin(_a0)
		local ax, ay = (_v1 - _v0) / _t0 * cos(_a0), (_v1 - _v0) / _t0 * sin(_a0)
		for i = 1, _t0 do
			road[i] = {}
			vx, vy = vx + ax, vy + ay
			_x, _y = _x + vx, _y + vy
			road[i][1], road[i][2] = _x, _y
		end
		return road
	else
		task.New(o, function()
			local v, a = GetV(o)
			local _v0, _v1, _a0, _t0 = v0 or v, v1 or v, a0 or a, t0 or 1
			SetV(o, _v0, _a0)
			SetA(o, (_v1 - _v0) / _t0, _a0, 0, 0, 0, false)
			task.Wait(_t0)
			SetA(o, 0, _a0, 0, 0, 0, false)
		end)
	end
end
egg.SimStrChV = SimStrChV
--简易的改变速度方向事件
function SimAngChV(o, _v0, _a0, _da, _t0, navi)
