			o.navi = true
		end
		local v0, a0, da, t0, v, a
		v, a = GetV(o)
		v0, a0, da, t0 = _v0 or v, _a0 or a, _da or 0, _t0 or 1
		da = da / t0
		for _ = 1, t0 do
			a0 = a0 + da
			SetV(o, v0, a0)
			task.Wait(1)
		end

	end)
end
