--一个可以同时均匀改变速度大小和方向的叠加事件
---@param o  @目标对象
---{[1] = v0, --初速度，为nil则获取目标当前速度
---[2] = v1, --末速度，为nil则获取目标当前速度
---[3] = a0, --初始方向，为nil则获取目标当前方向
---[4] = da, --方向变化总量
---[5] = tv, --速度大小变化时间
---[6] = ta, --速度方向变化时间
---}
function AddChV(o, v0, v1, a0, da, tv, ta)
	--change v 同时改变速度大小和方向事件(且可与其他事件叠加)
	task.New(o, function()
		local v, a, dv
		v, a = GetV(o)
		v0, v1, a0, da, tv, ta = v0 or v, v1 or v, a0 or a, da or 0, tv or 1, ta or 1
		ta = min(tv, ta)
		v, a = v0, a0
		dv, da = (v1 - v0) / tv, da / ta
		for i = 1, tv do
			if i <= ta then
				a = a + da
			end
			AddV1(o, dv, a)
			task.Wait(1)
		end
	end)
end
egg.AddChV = AddChV

--可叠加的简单匀变速圆周运动
local function AddCirMove(o, a0, da0, da1, r0, r1, t0, t1, wt, t2)
	task.New(o, function()
		local vx, vy
		vx, vy = r0 * (cos(a0 + da0) - cos(a0)), r0 * (sin(a0 + da0) - sin(a0))
		local dda, dr = (da1 - da0) / (t0 + t1), (r1 - r0) / t0
		--角速度和半径一起加
		for _ = 1, t0 do
			egg.AddV2(o, vx, vy)
			task.Wait(1)
			egg.AddV2(o, -vx, -vy)
			da0 = da0 + dda
			a0 = a0 + da0
			r0 = r0 + dr
			vx, vy = r0 * (cos(a0 + da0) - cos(a0)), r0 * (sin(a0 + da0) - sin(a0))
		end
		--只加角速度
		for _ = 1, t1 do
			egg.AddV2(o, vx, vy)
			task.Wait(1)
			egg.AddV2(o, -vx, -vy)
			da0 = da0 + dda
			a0 = a0 + da0
			vx, vy = r0 * (cos(a0 + da0) - cos(a0)), r0 * (sin(a0 + da0) - sin(a0))
		end
		--匀速时间
		for _ = 1, wt do
			egg.AddV2(o, vx, vy)
			task.Wait(1)
			egg.AddV2(o, -vx, -vy)
			a0 = a0 + da0
			vx, vy = r0 * (cos(a0 + da0) - cos(a0)), r0 * (sin(a0 + da0) - sin(a0))
		end
		if t2 then
			--在t2时间内匀减速停止运动，若不填则该运动不会停止
			dda = -da0 / t2
			for _ = 1, t2 do
				egg.AddV2(o, vx, vy)
				task.Wait(1)
				egg.AddV2(o, -vx, -vy)
				da0 = da0 + dda
				a0 = a0 + da0
				vx, vy = r0 * (cos(a0 + da0) - cos(a0)), r0 * (sin(a0 + da0) - sin(a0))
			end
		else
			--继续匀速下去吧
			for _ = 1, _infinite do
				egg.AddV2(o, vx, vy)
				task.Wait(1)
				egg.AddV2(o, -vx, -vy)
				a0 = a0 + da0
				vx, vy = r0 * (cos(a0 + da0) - cos(a0)), r0 * (sin(a0 + da0) - sin(a0))
			end
		end
	end)
end
egg.AddCirMove = AddCirMove

