--简易的均匀改变速度大小的叠加事件
---@param o  @目标对象
---@param v0  @设置叠加的初速度
---@param v1 @设置叠加的末速度
---@param a0 @设置方向
---@param t0 @设置变化时间
function AddSimStrChV(o, v0, v1, a0, t0, nowait, draw_t, wt)
	if nowait == true then
		local road = {}
		local _v0, _v1, _a0, _t0, v, a, dv, _draw_t
		local _x, _y = 0, 0
		v, a = 0, 0
		_v0, _v1, _a0, _t0, _draw_t = v0 or v, v1 or v, a0 or a, t0 or 1, draw_t or 0
		dv = (_v1 - _v0) / _t0
		local vx, vy = _v0 * cos(_a0), _v0 * sin(_a0)
		local ax, ay = dv * cos(_a0), dv * sin(_a0)
		for i = 1, _t0 do
			road[i] = {}
			vx, vy = vx + ax, vy + ay
			_x, _y = _x + vx, _y + vy
			road[i][1], road[i][2] = _x, _y
		end
		for i = _t0 + 1, _draw_t do
			road[i] = {}
			_x, _y = _x + vx, _y + vy
			road[i][1], road[i][2] = _x, _y
		end
		return road
	else
		task.New(o, function()
			task.Wait(wt or 0)
			local _v0, _v1, _a0, _t0, v, a, dv
			v, a = GetV(o)
			_v0, _v1, _a0, _t0 = v0 or v, v1 or v, a0 or a, t0 or 1
			dv = (_v1 - _v0) / _t0
			AddV1(o, _v0, _a0)
			AddA1(o, dv, _a0)
			task.Wait(_t0)
			AddA1(o, -dv, _a0)
		end)
	end
end

--简易的均匀改变速度大小的叠加事件
---@param o  @目标对象
---@param v0  @设置叠加的初速度
---@param v1 @设置叠加的末速度
---@param a0 @设置方向
---@param t0 @设置变化时间
---以上参数必填
local function AddSimStrChV(o, v0, v1, a0, t0, t1)
	t1 = t1 or 0
	local dv = (v1 - v0) / t0
	task.New(o, function()
		task.Wait(t1)
		AddV1(o, v0, a0)
		AddA1(o, dv, a0)
		task.Wait(t0)
		AddA1(o, -dv, a0)
	end)
end
egg.AddSimStrChV = AddSimStrChV

--叠加从0开始先加速后减速
local function AddAccDecChV(o, v, a, t1, wt, t2)
	v = v or 0
	a = a or 0
	t1 = t1 or 1 --变速时间
	wt = wt or 0 --匀速持续时间
	t2 = t2 or t1
	local dv = v / t1
	task.New(o, function()
		AddA1(o, dv, a)
		task.Wait(t1)
		AddA1(o, -dv, a)
		task.Wait(wt)
		dv = v / t2
		AddA1(o, -dv, a)
		task.Wait(t2)
		AddA1(o, dv, a)
	end)
end
egg.AddAccDecChV = AddAccDecChV

--配合叠加速度事件运算并描绘路径点集的表
function AddSimStrChV_Draw(dt, tmax, _road, add)
	local j = 1
	local road = _road
	for i = dt, tmax - 1 do
		road[i][1], road[i][2] = road[i][1] + add[j][1], road[i][2] + add[j][2]
		j = j + 1
	end
	return road
end





