--软停止，获取当前的速度值并将之逐渐减至0，可叠加
function StopCurrentV(o, t0)
	task.New(o, function()
		local v, a = GetV(o)
		local dvx, dvy = v * cos(a) / t0, v * sin(a) / t0
		for _ = 1, t0 do
			AddV2(o, dvx, dvy)
			task.Wait(1)
		end
	end)
end
egg.StopCurrentV = StopCurrentV
--硬停止，无论其他事件如何，在t0时间内一定能使v变成0，不可叠加
function HardStopCurrentV(o, t0)
	task.New(o, function()
		local v, a
		local dvx, dvy, t
		for i = 1, t0 do
			v, a = GetV(o)
			t = t0 + 1 - i
			dvx, dvy = v * cos(a) / t, v * sin(a) / t
			AddV2(o, dvx, dvy)
			task.Wait(1)
		end
		SetV(o, 0, a)  --防止减速完毕后产生的极小误差，所以手动设置速度为0一次
	end)
end

--简易的透明度均匀变化事件(最后一个参数若不为nil或false就改变目标的判定
function SimAlpCh(o, alpha0, alpha1, t0, colli)
	o._blend, o._r, o._g, o._b = o._blend or "", o._r or 255, o._g or 255, o._b or 255
	o._a = alpha0
	t0 = t0 or 60
	local dalp = (alpha1 - alpha0) / t0
	task.New(o, function()
		if colli then
			o.colli = false
		end
		for _ = 1, t0 do
			o._a = o._a + dalp
			task.Wait(1)
		end
		if colli then
			o.colli = true
		end
	end)
end
